const message = $json.messages?.[0] ?? $json.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
const metadata = $json.metadata ?? $json.entry?.[0]?.changes?.[0]?.value?.metadata;
if (!message?.from || message.type !== 'text' || !message.text?.body || !metadata?.phone_number_id) return [];
return [{ json: { patientPhone: String(message.from).replace(/\D/g, ''), patientMessage: message.text.body.trim(), phoneNumberId: String(metadata.phone_number_id) } }];
